  'Gestão': 'Gestión',
  'Tudo do negócio num lugar; toque em qualquer número para ver de onde vem. Ex.: Faturamento Bs 12.000 → toque → a lista das vendas que somam isso.': 'Todo el negocio en un lugar; toque cualquier número para ver de dónde viene. Ej.: Facturación Bs 12.000 → toque → la lista de ventas que suman eso.',
  'Assistente que pergunta o necessário: é cabelo? é serviço? Ex.: 60 cm | 2.008 g × 17,5 = Bs 35.140.': 'Asistente que pregunta lo necesario: ¿es cabello? ¿es servicio? Ej.: 60 cm | 2.008 g × 17,5 = Bs 35.140.',
  'Horários de cada profissional e unidade; avisa horário ocupado. Ex.: Sofia 15:00 Corte · Ana Paula.': 'Horarios de cada profesional y sucursal; avisa horario ocupado. Ej.: Sofía 15:00 Corte · Ana Paula.',
  'Dinheiro do dia por moeda: na mão e no banco. Ex.: ontem Bs 1.000 + hoje Bs 500 = Bs 1.500.': 'Dinero del día por moneda: en mano y en banco. Ej.: ayer Bs 1.000 + hoy Bs 500 = Bs 1.500.',
  'Pedido de compra com fotos/PDF que passa pela triagem até o estoque. Ex.: 40 kg bruto → Chegou → Conferido → Pago → No estoque.': 'Pedido de compra con fotos/PDF que pasa por la revisión hasta el inventario. Ej.: 40 kg en bruto → Llegó → Revisado → Pagado → En inventario.',
  'Lotes e itens, separar lote bruto e rastrear origem → destino. Ex.: 40 kg → 20 kg preto 60 cm + 19,5 kg castanho 50 cm.': 'Lotes e ítems, separar lote en bruto y rastrear origen → destino. Ej.: 40 kg → 20 kg negro 60 cm + 19,5 kg castaño 50 cm.',
  'Grade medida × comprador com o fator por grama. Ex.: 40 cm na coluna Henrique = 3,5.': 'Grilla medida × comprador con el factor por gramo. Ej.: 40 cm en la columna Henrique = 3,5.',
  'Clientes, fornecedores e a conta de cada um: quem me deve e a quem devo. Ex.: Henrique comprou Bs 89.420, pagou 70.000 → falta 19.420.': 'Clientes, proveedores y la cuenta de cada uno: quién me debe y a quién debo. Ej.: Henrique compró Bs 89.420, pagó 70.000 → falta 19.420.',
  'Organograma por salão, salários, comissões e entradas × saídas de cada unidade. Ex.: 4 funcionárias de Bs 3.000 = Bs 12.000/mês de custo.': 'Organigrama por salón, sueldos, comisiones e ingresos × egresos de cada sucursal. Ej.: 4 empleadas de Bs 3.000 = Bs 12.000/mes de costo.',
  'Dinheiro emprestado e tomado, parcelas e atrasos. Ex.: Bs 28.000 em 4× com 5% ao mês = 4 × Bs 8.400.': 'Dinero prestado y tomado, cuotas y atrasos. Ej.: Bs 28.000 en 4× con 5% al mes = 4 × Bs 8.400.',
  'Resultado e divisão entre sócias, livro caixa, inventário, balanço e o log de quem fez o quê. Ex.: resultado Bs 9.000 ÷ 2 sócias = Bs 4.500 cada.': 'Resultado y división entre socias, libro de caja, inventario, balance y el registro de quién hizo qué. Ej.: resultado Bs 9.000 ÷ 2 socias = Bs 4.500 cada una.',
  'Idioma, moedas e câmbio, sócias, módulos, usuários e backup. Ex.: trocar para espanhol num toque.': 'Idioma, monedas y tipo de cambio, socias, módulos, usuarios y respaldo. Ej.: cambiar a español con un toque.',
  'Senha de todos: 1234. Ex.: admin vê tudo; Sofia vê só a agenda e as vendas dela.': 'Contraseña de todos: 1234. Ej.: admin ve todo; Sofía ve solo su agenda y sus ventas.',

  // câmbio dinâmico/fixo
  'Base da internet (guardada no aparelho)': 'Base de internet (guardada en el dispositivo)',
  'Quando tem internet, o app busca a cotação de mercado e GUARDA aqui. Sem internet, usa a última guardada e mostra a data. Ex.: buscou às 08:00; ficou sem internet às 15:00 → as vendas usam a de 08:00.': 'Cuando hay internet, la app busca el tipo de cambio de mercado y lo GUARDA aquí. Sin internet, usa el último guardado y muestra la fecha. Ej.: buscó a las 08:00; se quedó sin internet a las 15:00 → las ventas usan el de las 08:00.',
  'Buscando…': 'Buscando…',
  'Buscar agora': 'Buscar ahora',
  'última base boa': 'última base buena',
  'Ainda não buscou na internet.': 'Todavía no buscó en internet.',
  'Toda cotação fica guardada com data e origem (internet ou digitada). Cada venda guarda a que usou: mudar o câmbio não muda o passado.': 'Todo tipo de cambio queda guardado con fecha y origen (internet o escrito). Cada venta guarda el que usó: cambiar el tipo de cambio no cambia el pasado.',
