  'Base': 'Base',
  'Dinâmico: venda e compra seguem a base da internet, com um ajuste em % se quiser. Ex.: base 6,96; venda −1,5% = 6,8556 (recebo dólar valendo um pouco menos); compra +1% = 7,0296.': 'Dinámico: venta y compra siguen la base de internet, con un ajuste en % si quiere. Ej.: base 6,96; venta −1,5% = 6,8556 (recibo dólar valiendo un poco menos); compra +1% = 7,0296.',
  'Fixo: você decide o valor e ele não muda com a internet. Ex.: para vender 1 USD = 6,90; para comprar 1 USD = 7,00.': 'Fijo: usted decide el valor y no cambia con internet. Ej.: para vender 1 USD = 6,90; para comprar 1 USD = 7,00.',
  'Venda: ajuste %': 'Venta: ajuste %',
  'Usado quando a cliente paga nesta moeda (venda, recebimento). Negativo = a moeda vale menos para você. Ex.: −1,5.': 'Se usa cuando la clienta paga en esta moneda (venta, cobro). Negativo = la moneda vale menos para usted. Ej.: −1,5.',
