  'Passo a passo + Revisar': 'Paso a paso + Revisar',
  'Fornecedor → O que veio → Detalhes, um embaixo do outro; o que não está aberto vira "+ Adicionar …". Registra quando o obrigatório está preenchido.': 'Proveedor → Lo que llegó → Detalles, uno debajo del otro; lo que no está abierto se vuelve "+ Agregar …". Registra cuando lo obligatorio está completo.',
  'Os mesmos passos e, no fim, um passo Revisar com o pedido inteiro antes de registrar.': 'Los mismos pasos y, al final, un paso Revisar con el pedido completo antes de registrar.',
  'Quem fez': 'Quién hizo',
