  'Compras ligadas': 'Compras vinculadas',
  'contas prestadas': 'cuentas rendidas',
  'Cada ação da viagem, da mais nova para a mais antiga, com quem fez e quando: gastos lançados ou anulados, adiantamentos, compras ligadas, encerramento. Toque na referência para abrir. Ex.: 03/11 · Paula lançou gasolina Bs 150 ↗': 'Cada acción del viaje, de la más nueva a la más antigua, con quién y cuándo: gastos cargados o anulados, adelantos, compras vinculadas, cierre. Toque la referencia para abrir. Ej.: 03/11 · Paula cargó gasolina Bs 150 ↗',
  'fez': 'hizo',
