  'Use para cabelo que já estava com você ou quando ainda não sabe o preço. Ex.: 3 kg do estoque antigo → registra 3 kg, valor fica para depois.': 'Use para cabello que ya tenía o cuando aún no sabe el precio. Ej.: 3 kg del inventario viejo → registra 3 kg, el valor queda para después.',
