  'Tirar este campo (limpa o que foi preenchido)': 'Quitar este campo (borra lo que se completó)',
  'Ex.: P-0008 (incremental) · M3 (sigla da Maria + 3ª compra dela) · ou um código digitado à mão.': 'Ej.: P-0008 (incremental) · M3 (sigla de María + su 3ª compra) · o un código escrito a mano.',
  'Ex.: coluna P.W. → 60 cm | 2.008 g × 17,5 = Bs 35.140. Muda o preço das linhas pela tabela.': 'Ej.: columna P.W. → 60 cm | 2.008 g × 17,5 = Bs 35.140. Cambia el precio de las filas por la tabla.',
  'Ex.: Paula comprou na viagem → a compra fica no nome dela (código por pessoa e o que ela trouxe).': 'Ej.: Paula compró en el viaje → la compra queda a su nombre (código por persona y lo que trajo).',
  'Ex.: Úmido · Embaraçado → fica no histórico e explica a perda na triagem.': 'Ej.: Húmedo · Enredado → queda en el historial y explica la pérdida en la selección.',
  'Ex.: foto do pedido, do cabelo e o comprovante de origem (nota ou recibo de quem vendeu).': 'Ej.: foto del pedido, del cabello y el comprobante de origen (nota o recibo de quien vendió).',
