  'sem saldo': 'sin saldo',
  'a custo': 'a costo',
  'o que ainda tem': 'lo que aún tiene',
  'parado: esperando para separar há mais de {n} dias (muda em Configurações › Etapas da compra). ✓ Etiqueta: já foi impressa (toque para ver ou reimprimir). 🏷 Sem etiqueta: ainda não imprimiu (toque para imprimir). ❓ para depois: ficou sem identificar numa separação. 🔗 juntado: pacote misturado (2 ou mais viraram um) ou com cabelo de mais de uma compra. Ex.: “parado” + há 12 dias = está esperando faz tempo, separe primeiro.': 'parado: esperando separar hace más de {n} días (se cambia en Configuración › Etapas de la compra). ✓ Etiqueta: ya fue impresa (toque para ver o reimprimir). 🏷 Sin etiqueta: aún no se imprimió (toque para imprimir). ❓ para después: quedó sin identificar en una separación. 🔗 juntado: paquete mezclado (2 o más se volvieron uno) o con cabello de más de una compra. Ej.: “parado” + hace 12 días = espera hace tiempo, sepárelo primero.',
  'Esperando para separar há mais de {n} dias': 'Esperando separar hace más de {n} días',
  'menos': 'menos',
  'Misturar compras numa separação só?': '¿Mezclar compras en una sola separación?',
  'Marque 2 ou mais pacotes e toque em “Juntar e separar”. Ex.: 2 kg da compra P-0005 + 4 kg da P-0007 → uma separação, cada grama sabe de onde veio.': 'Marque 2 o más paquetes y toque “Juntar y separar”. Ej.: 2 kg de la compra P-0005 + 4 kg de la P-0007 → una separación, cada gramo sabe de dónde vino.',
  'Juntar pacotes': 'Juntar paquetes',
  'Marque os pacotes que vão juntos (2 ou mais). A barra de baixo mostra “Juntar e separar”.': 'Marque los paquetes que van juntos (2 o más). La barra de abajo muestra “Juntar y separar”.',
  'Passos da separação': 'Pasos de la separación',
