  'nenhuma ainda': 'ninguna todavía',
  'nada': 'nada',
  'Tirar esta parte': 'Quitar esta parte',
  'Vou separar só uma parte agora': 'Voy a separar solo una parte ahora',
  'Quanto vai separar agora?': '¿Cuánto va a separar ahora?',
  'Passou do que entrou!': '¡Pasó de lo que entró!',
  'custo e códigos': 'costo y códigos',
  'passo {n} de {t}': 'paso {n} de {t}',
  'Os pacotes que vão virar um só antes de separar. A origem de cada grama fica guardada.': 'Los paquetes que se juntan antes de separar. El origen de cada gramo queda guardado.',
  'O pacote bruto que você vai dividir. Normalmente separa tudo; se for só uma parte agora, diga quanto.': 'El paquete bruto que va a dividir. Normalmente separa todo; si es solo una parte ahora, diga cuánto.',
  'Ex.: 2 kg da compra da Maria + 4 kg da do Celso = 6 kg para separar.': 'Ej.: 2 kg de la compra de María + 4 kg de la de Celso = 6 kg para separar.',
  'Ex.: chegou 10 kg, hoje vai separar só 4 kg → o resto continua bruto.': 'Ej.: llegaron 10 kg, hoy separa solo 4 kg → el resto sigue bruto.',
  'Cada parte vira um pacote novo, com etiqueta. Digite o peso e o que é: a medida e a categoria definem o preço pela tabela.': 'Cada parte se vuelve un paquete nuevo, con etiqueta. Escriba el peso y qué es: la medida y la categoría definen el precio por la tabla.',
  'Ex.: 3 kg de 60 cm Preto + 1,9 kg de 40 cm Castanho = 2 pacotes novos.': 'Ej.: 3 kg de 60 cm Negro + 1,9 kg de 40 cm Castaño = 2 paquetes nuevos.',
  'O que você ainda não sabe o que é fica guardado como “Não identificado” (aparece em Para depois na Triagem). Não é perda.': 'Lo que aún no sabe qué es queda guardado como “No identificado” (aparece en Para después en la Selección). No es pérdida.',
  'Ex.: 10 kg → 4 kg separados + 6 kg para depois → os 6 kg voltam para separar outro dia.': 'Ej.: 10 kg → 4 kg separados + 6 kg para después → los 6 kg vuelven para separar otro día.',
  'A conta tem que fechar: o que entrou = as partes + para depois + perda. Perda é o que não virou pacote (pontas, sujeira, cabelo ruim).': 'La cuenta tiene que cerrar: lo que entró = las partes + para después + pérdida. Pérdida es lo que no se volvió paquete (puntas, suciedad, cabello malo).',
  'Ex.: 10 kg = 9,4 kg em partes + 0 para depois + 600 g de perda (6%).': 'Ej.: 10 kg = 9,4 kg en partes + 0 para después + 600 g de pérdida (6%).',
