  'Qual preço mostrar nos prontos.': 'Qué precio mostrar en los listos.',
  'Muda o valor e a margem desta tela (ex.: 2.000 g × 17,5 da coluna P.W. = Bs 35.000). Não muda vendas feitas nem a tabela. Só nesta tela.': 'Cambia el valor y el margen de esta pantalla (ej.: 2.000 g × 17,5 de la columna P.W. = Bs 35.000). No cambia ventas hechas ni la tabla. Solo en esta pantalla.',
  'Agora: quadro.': 'Ahora: tablero.',
  'Agora: lista.': 'Ahora: lista.',
  'Lista: um pacote por linha com o botão Separar. Quadro: as colunas da triagem para arrastar os pacotes. Só muda a visão; fica lembrado neste aparelho.': 'Lista: un paquete por fila con el botón Separar. Tablero: las columnas de la selección para arrastrar los paquetes. Solo cambia la vista; queda guardado en este dispositivo.',
