  'Pedidos que ainda não terminaram (falta pagar, receber ou conferir). O cabelo já vai para a triagem quando a compra é registrada.': 'Pedidos que aún no terminaron (falta pagar, recibir o revisar). El cabello va a la selección apenas se registra la compra.',
  'Cabelo bruto esperando a triagem (separar por medida). Parado = esperando há mais dias do que o combinado em Configurações.': 'Cabello bruto esperando la selección (separar por medida). Parado = esperando más días de lo acordado en Configuración.',
  'Cabelo já separado, com saldo, no estoque. O valor é pela tabela de preço. Ex.: 2 kg × 17,5 = Bs 35.000.': 'Cabello ya separado, con saldo, en stock. El valor es por la tabla de precios. Ej.: 2 kg × 17,5 = Bs 35.000.',
  'Pacotes com saldo que ainda não têm etiqueta, ou cuja etiqueta mostra um peso que não bate mais (vendeu parte).': 'Paquetes con saldo que aún no tienen etiqueta, o cuya etiqueta muestra un peso que ya no coincide (se vendió parte).',
