  'Misturando compras: cada grama guarda de qual compra veio (aparece no pacote novo e na venda).': 'Mezclando compras: cada gramo guarda de qué compra vino (aparece en el paquete nuevo y en la venta).',
  'Tudo numa separação só: você diz as partes por medida.': 'Todo en una sola separación: dices las partes por medida.',
  'Diga as partes por medida; o que sobra é perda.': 'Di las partes por medida; lo que sobra es pérdida.',
  'Tem pacote já vendido na seleção.': 'Hay un paquete ya vendido en la selección.',
  'Vira um pacote só agora, com o peso somado; separa depois.': 'Se vuelve un solo paquete ahora, con el peso sumado; separas después.',
  'Junta sem separar: nasce um pacote novo com o peso de todos. Ex.: 1,2 kg + 3 kg → um pacote de 4,2 kg. Cada grama continua sabendo de qual compra veio.': 'Junta sin separar: nace un paquete nuevo con el peso de todos. Ej.: 1,2 kg + 3 kg → un paquete de 4,2 kg. Cada gramo sigue sabiendo de qué compra vino.',
  'Marque 2 ou mais pacotes para juntar.': 'Marca 2 o más paquetes para juntar.',
  'Imprimir (ou reimprimir) as etiquetas destes pacotes.': 'Imprimir (o reimprimir) las etiquetas de estos paquetes.',
  'Abre a tela Etiquetas com estes pacotes já marcados. Ex.: 2 pacotes sem etiqueta → imprime as 2 de uma vez.': 'Abre la pantalla Etiquetas con estos paquetes ya marcados. Ej.: 2 paquetes sin etiqueta → imprime las 2 de una vez.',
  'Vão para': 'Van a',
  'sem dividir: ficam prontos para vender.': 'sin dividir: quedan listos para vender.',
  'Conta como pronto para vender. O peso não muda.': 'Cuenta como listo para vender. El peso no cambia.',
  'Só muda a etapa no quadro (ex.: foi lavar). O peso não muda.': 'Solo cambia la etapa en el tablero (ej.: fue a lavar). El peso no cambia.',
  'já tem etiqueta': 'ya tiene etiqueta',
  'sem etiqueta': 'sin etiqueta',
  'todos sem etiqueta': 'todos sin etiqueta',
  'todos já têm etiqueta': 'todos ya tienen etiqueta',
  'Uma etiqueta por pacote, com o código, o peso de agora e o QR.': 'Una etiqueta por paquete, con el código, el peso de ahora y el QR.',
  'Imprime de uma vez as etiquetas dos marcados. Quem já tinha etiqueta ganha uma nova via com o peso de agora. Ex.: vendeu 2 kg de um pacote de 18 kg → a nova diz 16 kg.': 'Imprime de una vez las etiquetas de los marcados. Quien ya tenía etiqueta recibe una nueva copia con el peso de ahora. Ej.: vendió 2 kg de un paquete de 18 kg → la nueva dice 16 kg.',
  'Mudam só a ETAPA dos pacotes no quadro da triagem (não dividem nem mudam o peso). Ex.: foi lavar → Mover para “Lavando”; já veio separado → Marcar como triado.': 'Solo cambian la ETAPA de los paquetes en el tablero de selección (no dividen ni cambian el peso). Ej.: fue a lavar → Mover a “Lavando”; ya vino separado → Marcar como seleccionado.',
  'Abre Etiquetas com estes lotes já marcados.': 'Abre Etiquetas con estos lotes ya marcados.',
