  'Compra sem fornecedor: não há conta para acompanhar.': 'Compra sin proveedor: no hay cuenta para seguir.',
  'Etapas do pedido': 'Etapas del pedido',
  'Compra paga na hora (o normal): escolha a forma, confira o valor e toque em Pagar e concluir. O pedido vai direto até Concluído. Pagou só uma parte? O resto fica na conta do fornecedor.': 'Compra pagada en el momento (lo normal): elija la forma, revise el valor y toque Pagar y concluir. El pedido va directo a Concluido. ¿Pagó solo una parte? El resto queda en la cuenta del proveedor.',
