  'Em uma frase: a tabela diz o preço, a versão diz QUANDO valia, e cada venda guarda a versão que usou — o passado nunca muda.': 'En una frase: la tabla dice el precio, la versión dice CUÁNDO valía, y cada venta guarda la versión que usó — el pasado nunca cambia.',
  'Ex.:': 'Ej.:',
  'O que é uma tabela de preço': 'Qué es una tabla de precios',
  'É uma grade: cada linha é uma medida (cm) e cada coluna é um comprador ou canal. O número no cruzamento é o fator: quanto vale cada grama.': 'Es una grilla: cada fila es una medida (cm) y cada columna es un comprador o canal. El número del cruce es el factor: cuánto vale cada gramo.',
  '60 cm na coluna Helena = 16 → 500 g × 16 = Bs 8.000.': '60 cm en la columna Helena = 16 → 500 g × 16 = Bs 8.000.',
  'O que é uma versão': 'Qué es una versión',
  'Cada vez que alguém muda a tabela e publica, nasce uma versão nova (v1, v2, v3…). A anterior não some: fica guardada exatamente como era.': 'Cada vez que alguien cambia la tabla y publica, nace una versión nueva (v1, v2, v3…). La anterior no desaparece: queda guardada exactamente como era.',
  'v1 = 60 cm a 17 · v2 (depois do aumento) = 60 cm a 17,5.': 'v1 = 60 cm a 17 · v2 (después del aumento) = 60 cm a 17,5.',
  'Por que existem versões': 'Por qué existen versiones',
  'Para saber sempre qual preço valia em cada dia e conseguir comparar o que mudou, sem perder o passado.': 'Para saber siempre qué precio valía cada día y poder comparar lo que cambió, sin perder el pasado.',
  'O que a versão nova muda': 'Qué cambia la versión nueva',
  'Só as operações DEPOIS da publicação. As vendas e compras novas passam a usar a versão nova na hora.': 'Solo las operaciones DESPUÉS de la publicación. Las ventas y compras nuevas pasan a usar la versión nueva al momento.',
  'Publicou a v3 às 10h: a venda das 10h05 já usa a v3.': 'Publicó la v3 a las 10h: la venta de las 10h05 ya usa la v3.',
  'Por que a venda antiga não muda': 'Por qué la venta antigua no cambia',
  'A venda guarda a versão, o comprador e o fator que usou. Mudar a tabela depois não mexe nela: o caixa, a comissão e os relatórios continuam batendo.': 'La venta guarda la versión, el comprador y el factor que usó. Cambiar la tabla después no la toca: la caja, la comisión y los informes siguen cuadrando.',
  'Venda feita com a v2 fica com a v2 para sempre, mesmo depois da v3.': 'Una venta hecha con la v2 queda con la v2 para siempre, incluso después de la v3.',
  'Escolher o valor na venda': 'Elegir el valor en la venta',
  'No modo caixa, embaixo de "Nesta venda", fica a linha "Preço da tabela". Um toque mostra os compradores da tabela com o total de cada um; tocar num deles troca o valor de todos os pacotes na hora.': 'En el modo caja, debajo de "En esta venta", está la línea "Precio de la tabla". Un toque muestra los compradores de la tabla con el total de cada uno; tocar uno cambia el valor de todos los paquetes al momento.',
  'Normal (padrão) Bs 688,90 · Helena Bs 702,00 · P.W. Bs 720,00.': 'Normal (estándar) Bs 688,90 · Helena Bs 702,00 · P.W. Bs 720,00.',
  'O valor padrão': 'El valor estándar',
  'Sem escolher nada, a venda usa a coluna ligada à cliente (se ela tiver uma) ou a primeira coluna da tabela. Escolher é opcional: a venda segue normal sem mexer.': 'Sin elegir nada, la venta usa la columna vinculada a la clienta (si tiene una) o la primera columna de la tabla. Elegir es opcional: la venta sigue normal sin tocar nada.',
  'Como a troca reflete nas contas': 'Cómo el cambio se refleja en las cuentas',
  'Trocar o comprador recalcula na hora o valor de cada pacote, o total, o desconto em %, os impostos estimados e o que vai ser cobrado. O que aparece na tela é o que fica salvo na venda.': 'Cambiar el comprador recalcula al momento el valor de cada paquete, el total, el descuento en %, los impuestos estimados y lo que se cobrará. Lo que aparece en la pantalla es lo que queda guardado en la venta.',
  '367 g × 0,7 = Bs 256,90 → trocou para 0,8 → Bs 293,60 (o total e os impostos acompanham).': '367 g × 0,7 = Bs 256,90 → cambió a 0,8 → Bs 293,60 (el total y los impuestos acompañan).',
  'Onde a versão foi usada': 'Dónde se usó la versión',
  'Na aba "Onde foi usada", escolha a versão: aparecem só as vendas e compras daquela versão, com data, código, cliente, valor e quem fez.': 'En la pestaña "Dónde se usó", elija la versión: aparecen solo las ventas y compras de esa versión, con fecha, código, cliente, valor y quién la hizo.',
  'Rastreabilidade': 'Trazabilidad',
  'O Histórico mostra todas as versões (quando, quem e a nota) e compara quaisquer duas: o que subiu, desceu, entrou ou saiu. A Auditoria guarda cada publicação.': 'El Historial muestra todas las versiones (cuándo, quién y la nota) y compara dos cualquiera: lo que subió, bajó, entró o salió. La Auditoría guarda cada publicación.',
  'Mudar a tabela × criar outra tabela': 'Cambiar la tabla × crear otra tabla',
  'Mudar a grade e publicar cria uma VERSÃO nova da mesma tabela (mesma categoria, mesmo nome). Criar outra tabela é para outro tipo de cabelo (outra categoria, ex.: Tinte) ou para uma tabela que vai valer a partir de uma data.': 'Cambiar la grilla y publicar crea una VERSIÓN nueva de la misma tabla (misma categoría, mismo nombre). Crear otra tabla es para otro tipo de cabello (otra categoría, ej.: Tinte) o para una tabla que valdrá a partir de una fecha.',
  'Cuidados ao mudar preços': 'Cuidados al cambiar precios',
  'Confira antes de publicar (a barra mostra quantas células mudaram) e escreva na nota o porquê. Mudança errada se corrige publicando outra versão — a errada continua no histórico.': 'Revise antes de publicar (la barra muestra cuántas celdas cambiaron) y escriba en la nota el porqué. Un cambio equivocado se corrige publicando otra versión — la equivocada sigue en el historial.',
  'Valor mudado à mão numa venda aparece marcado "fator mudado à mão" em Onde foi usada.': 'Un valor cambiado a mano en una venta aparece marcado "factor cambiado a mano" en Dónde se usó.',
