  'Para quando a etiqueta já foi feita em outro lugar ou vai ser impressa depois. Fica registrado quem marcou e quando, igual a imprimir. Ex.: imprimiu as etiquetas de L-0021, L-0022 e L-0023 na outra loja → marque aqui.': 'Para cuando la etiqueta ya se hizo en otro lugar o se imprimirá después. Queda registrado quién marcó y cuándo, igual que al imprimir. Ej.: imprimió las etiquetas de L-0021, L-0022 y L-0023 en la otra tienda → márquelas aquí.',
