  'Desligado: vende sem abrir turno.': 'Desactivado: vende sin abrir turno.',
  'Ligado: a funcionária ABRE o turno (com o troco que recebeu) antes de vender ou lançar dinheiro, e fecha contando o dinheiro. No Caixa › Turnos você vê de que horas a que horas ela trabalhou, as vendas e a média por hora. Desligado: o turno começa sozinho e vender não depende dele. Ex.: abre às 08:00 com Bs 100 de troco, fecha às 14:00.': 'Activado: la empleada ABRE el turno (con el cambio que recibió) antes de vender o registrar dinero, y lo cierra contando el dinero. En Caja › Turnos usted ve de qué hora a qué hora trabajó, las ventas y el promedio por hora. Desactivado: el turno empieza solo y vender no depende de él. Ej.: abre a las 08:00 con Bs 100 de cambio, cierra a las 14:00.',
