  'Próximo passo: gerar 1 etiqueta': 'Próximo paso: generar 1 etiqueta',
  'Próximo passo: gerar {n} etiquetas': 'Próximo paso: generar {n} etiquetas',
  'Estimativa desta venda — não é exatamente o que você vai pagar.': 'Estimación de esta venta — no es exactamente lo que usted va a pagar.',
  'O imposto de verdade é calculado no período, com créditos e compensações (na Bolívia: o IVA das compras com fatura abate o das vendas e o IUE pago abate o IT). Só informativo: não muda o valor cobrado.': 'El impuesto real se calcula en el período, con créditos y compensaciones (en Bolivia: el IVA de las compras con factura descuenta el de las ventas y el IUE pagado compensa el IT). Solo informativo: no cambia el valor cobrado.',
  'Estimativa — não é exatamente o que você vai pagar.': 'Estimación — no es exactamente lo que usted va a pagar.',
  'O que é e por que existe': 'Qué es y por qué existe',
  'Por que existe': 'Por qué existe',
  'Na prática': 'En la práctica',
  'O que é, de onde vem e por que existe': 'Qué es, de dónde viene y por qué existe',
  'De onde vem': 'De dónde viene',
  'Como a conta é feita': 'Cómo se hace la cuenta',
  'Na prática (o que se paga de verdade)': 'En la práctica (lo que se paga de verdad)',
  'Como funciona: {r}': 'Cómo funciona: {r}',
  'Quem está nele': 'Quién está en él',
  'Como paga': 'Cómo paga',
  'Os valores do sistema são estimativas para acompanhar o negócio — não substituem o contador. Confirme com ele o regime e as taxas.': 'Los valores del sistema son estimaciones para seguir el negocio — no reemplazan al contador. Confirme con él el régimen y las tasas.',
  'RTS: paga uma cota fixa a cada dois meses — não há IVA nem IT por venda.': 'RTS: paga una cuota fija cada dos meses — no hay IVA ni IT por venta.',
  'Vendas sem fatura: não há IVA na venda (o IT continua).': 'Ventas sin factura: no hay IVA en la venta (el IT sigue).',
  'É o imposto sobre o consumo da Bolívia: quem compra paga, e a loja só repassa ao fisco. Por isso vem DENTRO do preço — dos Bs 100 cobrados, Bs 13 são do governo.': 'Es el impuesto al consumo de Bolivia: quien compra lo paga y la tienda solo lo pasa al fisco. Por eso viene DENTRO del precio — de los Bs 100 cobrados, Bs 13 son del Estado.',
  'Todo mês se paga o IVA das vendas MENOS o IVA das compras feitas com fatura (crédito fiscal). Cabelo comprado sem fatura não dá crédito. Venda sem fatura (ou regime RTS) não tem IVA por venda.': 'Cada mes se paga el IVA de las ventas MENOS el IVA de las compras hechas con factura (crédito fiscal). El cabello comprado sin factura no da crédito. La venta sin factura (o en el RTS) no tiene IVA por venta.',
  'É um imposto sobre o faturamento bruto: incide sobre tudo o que entra, dê lucro ou não. Existe para o Estado arrecadar sobre cada transação.': 'Es un impuesto sobre el ingreso bruto: se aplica a todo lo que entra, haya ganancia o no. Existe para que el Estado recaude sobre cada transacción.',
  'O IUE (25% sobre o lucro, pago uma vez por ano) já pago se desconta do IT dos meses seguintes. Quem está no RTS não paga IT por venda.': 'El IUE (25% sobre la utilidad, pagado una vez al año) ya pagado se descuenta del IT de los meses siguientes. Quien está en el RTS no paga IT por venta.',
  'É o regime simplificado do Brasil para pequenas empresas: junta vários impostos (IRPJ, CSLL, PIS, COFINS, ICMS/ISS) numa guia só, o DAS.': 'Es el régimen simplificado de Brasil para pequeñas empresas: junta varios impuestos (IRPJ, CSLL, PIS, COFINS, ICMS/ISS) en una sola guía, el DAS.',
  'A alíquota efetiva muda com o faturamento dos últimos 12 meses: o valor aqui é uma estimativa com a taxa configurada.': 'La alícuota efectiva cambia con la facturación de los últimos 12 meses: el valor aquí es una estimación con la tasa configurada.',
  'Empresas e comércios que emitem fatura (NIT no Régimen General). É o padrão.': 'Empresas y comercios que emiten factura (NIT en el Régimen General). Es el estándar.',
  'Cada venda com fatura tem IVA 13% (dentro do preço) e IT 3%. Todo mês: IVA das vendas − IVA das compras com fatura, mais o IT. No fim do ano, IUE 25% sobre o lucro — e esse IUE se desconta do IT depois.': 'Cada venta con factura tiene IVA 13% (dentro del precio) e IT 3%. Cada mes: IVA de las ventas − IVA de las compras con factura, más el IT. Al final del año, IUE 25% sobre la utilidad — y ese IUE se descuenta del IT después.',
  'Pequenos comerciantes e artesãos com capital e vendas pequenos (dentro dos limites do RTS).': 'Pequeños comerciantes y artesanos con capital y ventas pequeños (dentro de los límites del RTS).',
  'Paga uma cota FIXA a cada dois meses, conforme a categoria. Não há IVA nem IT por venda e não se emite fatura com crédito fiscal — por isso a venda não mostra imposto.': 'Paga una cuota FIJA cada dos meses, según la categoría. No hay IVA ni IT por venta y no se emite factura con crédito fiscal — por eso la venta no muestra impuesto.',
  'Micro e pequenas empresas no Brasil (faturamento até o limite do Simples).': 'Micro y pequeñas empresas en Brasil (facturación hasta el límite del Simples).',
  'Uma guia só por mês (DAS) com uma alíquota efetiva sobre a receita bruta, que sobe conforme o faturamento dos últimos 12 meses.': 'Una sola guía por mes (DAS) con una alícuota efectiva sobre el ingreso bruto, que sube según la facturación de los últimos 12 meses.',
  'Empresas no Brasil acima do Simples (ou que preferem este regime).': 'Empresas en Brasil por encima del Simples (o que prefieren este régimen).',
  'PIS e COFINS sobre a receita todo mês; IRPJ e CSLL a cada trimestre sobre um lucro "presumido" (uma porcentagem fixa da receita), não sobre o lucro real.': 'PIS y COFINS sobre el ingreso cada mes; IRPJ y CSLL cada trimestre sobre una utilidad "presumida" (un porcentaje fijo del ingreso), no sobre la utilidad real.',
  'Impostos na nota': 'Impuestos en la nota',
  'Imprimir nota': 'Imprimir nota',
  'Só nesta impressão — o padrão de todas as notas fica em Configurações › Geral.': 'Solo en esta impresión — el estándar de todas las notas está en Configuraciones › General.',
  'Para a nota sair completa, falta: {x}.': 'Para que la nota salga completa, falta: {x}.',
  'Dados da empresa': 'Datos de la empresa',
  'É uma nota de venda (documento comercial), não uma factura: o sistema não está ligado ao SIN, por isso não tem código de autorização nem QR.': 'Es una nota de venta (documento comercial), no una factura: el sistema no está conectado al SIN, por eso no tiene código de autorización ni QR.',
  'Divisão interna (não sai na nota)': 'División interna (no sale en la nota)',
  'Tudo o que aconteceu com este cabelo: quanto entrou, quanto se perdeu na triagem, quanto foi vendido e quanto ainda está no estoque.': 'Todo lo que pasó con este cabello: cuánto entró, cuánto se perdió en la clasificación, cuánto se vendió y cuánto queda en el inventario.',
  'Nota de venda': 'Nota de venta',
  'Exibir detalhamento de impostos nas notas impressas': 'Mostrar el detalle de impuestos en las notas impresas',
  'Ligado: a nota mostra os impostos estimados (ex.: IVA 13% e IT 3% dentro do preço). Desligado: não mostra. O total da venda é o mesmo nos dois casos.': 'Activado: la nota muestra los impuestos estimados (ej.: IVA 13% e IT 3% dentro del precio). Desactivado: no los muestra. El total de la venta es el mismo en los dos casos.',
  'O documento da venda (aba Resumo da venda): o papel que sai por padrão e se mostra o detalhe dos impostos. Na venda dá para trocar só naquela impressão.': 'El documento de la venta (pestaña Resumen de la venta): el papel que sale por defecto y si muestra el detalle de impuestos. En la venta se puede cambiar solo para esa impresión.',
