  'Só muda o que aparece na agenda: o feriado não bloqueia nada e não muda nenhuma data.': 'Solo cambia lo que aparece en la agenda: el feriado no bloquea nada ni cambia ninguna fecha.',
  'O que falta nesta venda': 'Lo que falta en esta venta',
  'desde hoje': 'desde hoy',
  'Anexar comprovante': 'Adjuntar comprobante',
  'A venda foi concluída, mas parte do valor ainda não entrou no caixa. Enquanto faltar, o valor fica na conta da cliente (e aparece no Painel em "Falta receber"). Resolva registrando o pagamento quando ela pagar.': 'La venta se concluyó, pero parte del valor todavía no entró a la caja. Mientras falte, el valor queda en la cuenta de la clienta (y aparece en el Panel en "Falta cobrar"). Resuélvalo registrando el pago cuando ella pague.',
  'O pagamento não foi em dinheiro vivo (QR, transferência, cartão…): guarde o comprovante para conferir com o banco e ter prova se a cliente contestar. Resolva anexando a foto ou o PDF do comprovante em Arquivos.': 'El pago no fue en efectivo (QR, transferencia, tarjeta…): guarde el comprobante para verificar con el banco y tener prueba si la clienta reclama. Resuélvalo adjuntando la foto o el PDF del comprobante en Archivos.',
