  'O IT incide sobre o faturamento bruto e entra como gasto, depois do lucro bruto (Ley 843). Estimado.': 'El IT grava los ingresos brutos y entra como gasto, después de la utilidad bruta (Ley 843). Estimado.',
  'Lucro bruto − IT. O IUE (25%) é anual, sobre o lucro do ano, por isso não se reparte por venda.': 'Utilidad bruta − IT. El IUE (25%) es anual, sobre la utilidad del año, por eso no se reparte por venta.',
  'A mesma ordem do Estado de Resultados do relatório contábil, para uma venda só: primeiro o que está na factura (preço de lista, descontos, total faturado); depois o IVA (do fisco), o custo e o IT. O IUE é anual (sobre o lucro do ano) e por isso não se reparte por venda. Impostos estimados.': 'El mismo orden del Estado de Resultados del informe contable, para una sola venta: primero lo que está en la factura (precio de lista, descuentos, total facturado); después el IVA (del fisco), el costo y el IT. El IUE es anual (sobre la utilidad del año) y por eso no se reparte por venta. Impuestos estimados.',
