  'Demonstrativo interno de apoio tributário: não é declaração ao SIN nem substitui o contador. Impostos são ESTIMADOS com as regras do exercício.': 'Demostrativo interno de apoyo tributario: no es una declaración ante el SIN ni reemplaza al contador. Los impuestos son ESTIMADOS con las reglas de la gestión.',
