  'Fechar congela os números e a versão das regras usadas (o documento do fechamento não muda depois). Correções continuam possíveis e ficam no histórico.': 'Cerrar congela los números y la versión de las reglas usadas (el documento del cierre no cambia después). Las correcciones siguen siendo posibles y quedan en el historial.',
  'Enquadramento a confirmar com o contador': 'Encuadramiento a confirmar con el contador',
  'Não existe código CAEB-SIN que diga "cabelo humano". Os mais próximos: 4649400 (venda por atacado de produtos de beleza), 4772200 (varejo de cosméticos) e 9602100 (salão). Só classificar e revender é atividade comercial (cierre 31/12); se o NIT estiver como industrial, o cierre é 31/03.': 'No existe un código CAEB-SIN que diga "cabello humano". Los más cercanos: 4649400 (venta al por mayor de productos de belleza), 4772200 (venta al por menor de cosméticos) y 9602100 (peluquería). Solo clasificar y revender es actividad comercial (cierre 31/12); si el NIT figura como industrial, el cierre es 31/03.',
