  'Receita − descontos − custo do que foi vendido − insumos dos serviços − comissões = lucro bruto; − gastos = resultado.': 'Ingresos − descuentos − costo de lo vendido − insumos de los servicios − comisiones = utilidad bruta; − gastos = resultado.',
