  'Resultado × parte de cada uma − o que já retirou = quanto falta acertar (o “÷ 2” do caderno). As partes vêm de Configurações › Sócias.': 'Resultado × parte de cada una − lo que ya retiró = cuánto falta ajustar (el “÷ 2” del cuaderno). Las partes vienen de Configuración › Socias.',
