  'Kg comprados': 'Kg comprados',
  '(Cabelo + gastos das viagens) ÷ kg comprados, de todas as viagens da lista.': '(Cabello + gastos de los viajes) ÷ kg comprados, de todos los viajes de la lista.',
  'Resultado das viagens': 'Resultado de los viajes',
  'Receita das vendas do cabelo destas viagens − o custo do que já saiu. Enquanto tem cabelo em estoque, tende a ser menor.': 'Ingresos de las ventas del cabello de estos viajes − el costo de lo que ya salió. Mientras haya cabello en inventario, tiende a ser menor.',
  'Quanto custou cada kg': 'Cuánto costó cada kg',
  'gastos da viagem': 'gastos del viaje',
  'Custo por kg = o que se pagou pelo cabelo ÷ kg + o gasto da viagem (combustível, hospedagem…) ÷ kg. Quanto menor, melhor.': 'Costo por kg = lo que se pagó por el cabello ÷ kg + el gasto del viaje (combustible, hospedaje…) ÷ kg. Cuanto menor, mejor.',
  'mais barata': 'más barato',
  'resultado': 'resultado',
