  'Nome completo': 'Nombre completo',
  'Só os números do NIT, como está no certificado do SIN. Ex.: 1234567019.': 'Solo los números del NIT, como está en el certificado del SIN. Ej.: 1234567019.',
  'Ler vários códigos': 'Leer varios códigos',
  'Pode sair ou fechar o app: nada se perde. Ela volta aqui no Modo caixa.': 'Puede salir o cerrar la app: no se pierde nada. Vuelve aquí en el Modo caja.',
  'estimado': 'estimado',
  'Simular internet (teste)': 'Simular internet (prueba)',
  'Para ver como o app fica quando os dados vierem do servidor: cada tela espera o tempo escolhido antes de mostrar os dados (aparece o carregamento). Só neste aparelho; não muda nenhum dado.': 'Para ver cómo queda la app cuando los datos vengan del servidor: cada pantalla espera el tiempo elegido antes de mostrar los datos (aparece la carga). Solo en este dispositivo; no cambia ningún dato.',
