  'Vale para todo usuário com perfil Funcionário (também a gerente). O admin sempre vê e faz tudo. Tema, idioma e a própria senha a funcionária sempre pode mudar.': 'Vale para todo usuario con perfil Funcionario (también la gerente). El admin siempre ve y hace todo. Tema, idioma y su propia contraseña la funcionaria siempre puede cambiar.',
