  'Pode vender': 'Puede vender',
  'Os caminhos do “+ Nova venda” que aparecem para ela. Desligado some do menu e a venda é recusada também no servidor.': 'Los caminos de “+ Nueva venta” que le aparecen. Apagado desaparece del menú y la venta también se rechaza en el servidor.',
  'Vê na agenda': 'Ve en la agenda',
  'O que aparece na agenda dela (e na legenda). Viagem e empréstimo são do admin: no padrão ficam desligados.': 'Lo que aparece en su agenda (y en la leyenda). Viaje y préstamo son del admin: por defecto quedan apagados.',
  'Telas além do básico': 'Pantallas además de lo básico',
  'O básico é Vender, Agenda, Equipe e Configurações (tema, idioma, senha). Estas ficam só com o admin até serem ligadas aqui (ex.: Pessoas para quem é gerente).': 'Lo básico es Vender, Agenda, Equipo y Configuración (tema, idioma, contraseña). Estas quedan solo con el admin hasta encenderlas aquí (ej.: Personas para quien es gerente).',
  'A maioria da equipe é boliviana: espanhol no padrão. Cada aparelho ainda pode trocar no cabeçalho de Configurações.': 'La mayoría del equipo es boliviana: español por defecto. Cada dispositivo todavía puede cambiarlo en el encabezado de Configuración.',
  'Español': 'Español',
  'Português': 'Português',
  'Configurações que ela vê': 'Configuraciones que ella ve',
  'Além de tema, idioma e a própria senha. Usuários, Dados, Módulos e esta tela ficam sempre só do admin. O que ela não pode mudar continua protegido: só o admin salva.': 'Además de tema, idioma y su propia contraseña. Usuarios, Datos, Módulos y esta pantalla quedan siempre solo del admin. Lo que ella no puede cambiar sigue protegido: solo el admin guarda.',
