  // 10/11/2026: impostos oficiais × cadastrados, relatórios em lista, mudar parcela, emprestar e adiantar mais
  'Os oficiais (🏛) são os da lei: na Bolívia, IVA 13% e IT 3% — e o IUE 25% sobre a utilidade, anual, no Imposto de Renda. Você pode cadastrar outros (📝): eles também entram nos Relatórios (Estados financeiros e Imposto de Renda), sempre com o selo de cadastro.': 'Los oficiales (🏛) son los de la ley: en Bolivia, IVA 13% e IT 3% — y el IUE 25% sobre la utilidad, anual, en el Impuesto a la Renta. Puede registrar otros (📝): también entran en los Reportes (Estados financieros e Impuesto a la Renta), siempre con el sello de registro.',
