  'Na ordem das normas bolivianas: o IVA sai das vendas (o preço já inclui IVA), o IT 3% é gasto e o IUE é 25% da utilidade. Para o SIN, o contador entrega por ano o Formulario 500 (IUE) e o 605 (estados financieros), até 120 dias depois do cierre — com o Balance, o Estado de Resultados e as notas.': 'En el orden de las normas bolivianas: el IVA sale de las ventas (el precio ya incluye IVA), el IT 3% es gasto y el IUE es 25% de la utilidad. Para el SIN, el contador presenta cada año el Formulario 500 (IUE) y el 605 (estados financieros), hasta 120 días después del cierre — con el Balance, el Estado de Resultados y las notas.',
  'Impostos oficiais: IVA e IT (e o IUE, anual). As taxas e os impostos que você cadastrar vêm de Configurações › Fiscal › Impostos — os cadastrados aparecem com o selo “📝 cadastro”.': 'Impuestos oficiales: IVA e IT (y el IUE, anual). Las tasas y los impuestos que usted registre vienen de Configuración › Fiscal › Impuestos — los registrados aparecen con el sello “📝 registro”.',
